		Map<PEdge, Integer> bag = new HashMap<>(edges.size());
		edges.forEach(edge -> {
			bag.merge(edge, 1, Integer::sum);
		});

		List<PEdge> innerEdges = bag.entrySet().stream().filter(e -> e.getValue() > 1).map(e -> e.getKey()).collect(Collectors.toList());
