                                    ((CraftPlayer) p).getHandle().playerConnection
                                        .sendPacket(new PacketPlayOutEntityHeadRotation(target, (byte) finalHead));
                                    NPC.setArmor(p, target, arm);
                                });
                            this.cancel();
                        }
